window.docContents[155].resolve({"/#Functional-Programming-in-Lean--Monad-Transformers--Combining-IO-and-Reader--Exercises--Controlling-the-Display-of-Dotfiles":{"contents":"Files whose names begin with a dot character ('.') typically represent files that should usually be hidden, such as source-control metadata and configuration files.\nModify doug with an option to show or hide filenames that begin with a dot.\nThis option should be controlled with a -a command-line option.\n\n","context":"Functional Programming in Lean\u0009Monad Transformers\u0009Combining IO and Reader\u0009Exercises","header":"6.1.4.1. Controlling the Display of Dotfiles","id":"/#Functional-Programming-in-Lean--Monad-Transformers--Combining-IO-and-Reader--Exercises--Controlling-the-Display-of-Dotfiles"},"/#about-the-author":{"contents":"David Thrane Christiansen has been using functional languages for twenty years, and dependent types for ten.\nTogether with Daniel P. Friedman, he wrote The Little Typer, an introduction to the key ideas of dependent type theory.\nHe has a Ph.D. from the IT University of Copenhagen.\nDuring his studies, he was a major contributor to the first version of the Idris language.\nSince leaving academia, he has worked as a software developer at Galois in Portland, Oregon and Deon Digital in Copenhagen, Denmark, and he was the Executive Director of the Haskell Foundation.\nAt the time of writing, he is employed at the Lean Focused Research Organization working full-time on Lean.\n\n","context":"Functional Programming in Lean\u0009Introduction","header":"About the Author","id":"/#about-the-author"}});